// Parse User Request — memory now comes from the Data Table row (input $json),
// and trigger data is read via explicit node references (Load Data Table Memory
// sits between the trigger and this node).
function getTrigger() {
  try { const c = $('When chat message received'); if (c && c.item && c.item.json && Object.keys(c.item.json).length) return c.item.json; } catch (e) {}
  try { const w = $('CrisisLens Webhook'); if (w && w.item && w.item.json && Object.keys(w.item.json).length) return w.item.json; } catch (e) {}
  return $json ?? {};
}

const raw = getTrigger();
const body = raw.body && typeof raw.body === 'object' ? raw.body : {};
const input = { ...raw, ...body };
const suppliedContext = input.region_context && typeof input.region_context === 'object' ? input.region_context : {};
const suppliedLatitude = Number(input.latitude ?? suppliedContext.latitude);
const suppliedLongitude = Number(input.longitude ?? suppliedContext.longitude);
const hasSuppliedCoordinates = Number.isFinite(suppliedLatitude) && Number.isFinite(suppliedLongitude);

const chatInput = String(raw.chatInput ?? body.chatInput ?? '').trim();
// Never let an empty query object become [object Object]: only accept strings.
const message = String(
  (typeof input.message === 'string' && input.message) ||
  (typeof input.query === 'string' && input.query) ||
  (typeof input.chatInput === 'string' && input.chatInput) ||
  (typeof body.chatInput === 'string' && body.chatInput) ||
  chatInput || ''
).trim();
const explicitRegion = String((typeof input.region === 'string' && input.region) || input.region_name || suppliedContext.name || suppliedContext.city || suppliedContext.country || '').trim();
const sessionId = String(raw.session_id ?? raw.sessionId ?? body.session_id ?? body.sessionId ?? '').trim() || 'anonymous';
const source_channel = (raw.headers !== undefined || raw.body !== undefined) ? 'webhook' : 'chat';
const classificationMessage = [message, input.routing_query].filter(Boolean).join(' ');
const lower = classificationMessage.toLowerCase();
const asksRegionAccess = /(?:what|which|show|list|tell).{0,28}(?:regions?|locations?|cities|countries).{0,24}(?:access|support|cover|available)|(?:regions?|locations?).{0,24}(?:do you have|can you access|are supported)/i.test(classificationMessage) || /(?:کن علاقوں|کون سے علاقوں|علاقوں تک رسائی|دستیاب علاقے|علاقوں کی فہرست)/.test(classificationMessage);
const availableRegionSource = Array.isArray(input.available_regions) ? input.available_regions : [];
const accessibleRegionNames = [...new Set(availableRegionSource.map((item) => typeof item === 'string' ? item : (item && (item.name || item.region_name || item.city || item.country))).filter(Boolean))];

// ---- Load memory from the Data Table row (replaces $getWorkflowStaticData) ----
function loadMemory() {
  const result = { data: {}, ok: true, error: '' };
  const row = $json ?? {};
  try {
    if (row && typeof row.memory_json === 'string' && row.memory_json.trim()) {
      result.data = JSON.parse(row.memory_json) || {};
      return result;
    }
    // Fallback: reconstruct from explicit columns if memory_json is absent.
    if (row && (row.session_id || row.active_region || row.region_key)) {
      let assessment = null;
      try { assessment = row.last_assessment ? JSON.parse(row.last_assessment) : null; } catch (e) {}
      result.data = {
        last_region: row.active_region || '',
        active_region: row.active_region || '',
        region_key: row.region_key || '',
        latitude: row.latitude ?? null,
        longitude: row.longitude ?? null,
        last_intent: row.last_intent || '',
        last_stakeholder: row.last_stakeholder || '',
        last_threat_level: row.last_threat_level || '',
        last_assessment: assessment,
        updated_at: row.updated_at || '',
      };
    }
  } catch (error) {
    result.ok = false;
    result.error = String(error && error.message || error);
  }
  return result;
}

const memoryLoad = loadMemory();
const memory = memoryLoad.data || {};
const recentAssessment = memory.last_assessment && memory.updated_at && (Date.now() - Date.parse(memory.updated_at) < 10 * 60 * 1000);

function cleanRegion(value) {
  return String(value || '')
    .replace(/\b(and\s+)?what\s+should\s+[^?.]+/gi, ' ')
    .replace(/\bwhat\s+actions\s+should\s+[^?.]+/gi, ' ')
    .replace(/\b(currently|today|right now|please|now|instead)\b/gi, ' ')
    .replace(/[?!.]+$/g, '')
    .replace(/^\s*(are\s+there|is\s+there|show\s+me|tell\s+me|what\s+are|what\s+is|check)\s+/i, '')
    .replace(/^\s*(current\s+)?(threats?|risks?|weather\s+risks?|wildfires?|fires?|floods?|flooding|weather|conditions?)\s+(affecting|near|in|for|around)?\s*/i, '')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/,$/, '')
    .trim();
}

function isLocationOnlyCandidate(text) {
  const cleaned = cleanRegion(text).replace(/[.,!?]/g, '').trim();
  if (!/^[A-Za-zÀ-ÿ][A-Za-zÀ-ÿ\s,'-]{2,90}$/.test(cleaned)) return false;
  return !/\b(i|i'm|im|am|feel|feeling|felt|hot|cold|freezing|sick|unwell|thirsty|dizzy|tired|what|why|how|threat|risk|weather|should|do|public|farmers|hello|help|dangerous|happening|evidence|supports)\b/i.test(cleaned);
}

function extractRegion(text) {
  if (!text) return '';
  const patterns = [
    /\b(?:affecting|near|around|in|for|at)\s+([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ\s,'-]{2,90}?)(?:\s+and\s+(?:what|which|who|how)\b|\s+what\s+should\b|\?|\.|$)/i,
    /\b(?:threats?|risks?|wildfires?|fires?|floods?|flooding|weather\s+risks?|weather)\s+(?:affecting|near|around|in|for|at)\s+([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ\s,'-]{2,90}?)(?:\s+and\s+(?:what|which|who|how)\b|\s+what\s+should\b|\?|\.|$)/i,
  ];
  for (const pattern of patterns) {
    const match = text.match(pattern);
    if (match?.[1]) return cleanRegion(match[1]);
  }
  const known = [];
  for (const [region, pattern] of known) {
    if (pattern.test(text)) return region;
  }
  return isLocationOnlyCandidate(text) ? cleanRegion(text) : '';
}

function intentFromPending(pending) {
  const value = String(pending || '').toLowerCase();
  if (['weather_heat_check', 'weather_temperature_check', 'weather_check', 'heat_check', 'cold_check'].includes(value)) return 'weather';
  if (['threat_assessment', 'general_threats', 'full_threat_assessment'].includes(value)) return 'general_threats';
  return value || '';
}

function pendingFromIntent(intent, text) {
  if (intent === 'weather' || intent === 'heat' || /\b(hot|heat|freezing|cold|temperature|weather)\b/i.test(text)) return 'weather_heat_check';
  return 'general_threats';
}

let intent = 'general_threats';
if (/^(hello|hi|hey)\b/.test(lower) && lower.split(/\s+/).length <= 4) intent = 'greeting';
else if (/^(help|what can you do)\b/.test(lower)) intent = 'help';
else if (/\bwhy\b|happening|cause|evidence|supports?/i.test(classificationMessage)) intent = 'evidence';
else if (/what should|what do|actions?|recommend|advice|farmers do|residents take|public do/i.test(classificationMessage)) intent = 'actions';
else if (/weather|temperature|rain|wind|forecast|feel hot|very hot|freezing|feels cold/.test(lower) && !/threat|risk|flood|wildfire|fire|disaster|evidence|report|why|action|should/.test(lower)) intent = 'weather';
else if (/wildfire|forest fire|active fire|fire threat|thermal anomaly/.test(lower)) intent = 'wildfire';
else if (/flood|flooding|heavy rain|river/.test(lower)) intent = 'flood';
else if (/earthquake|seismic/.test(lower)) intent = 'earthquake';
else if (/cyclone|hurricane|typhoon|storm/.test(lower)) intent = 'storm';
else if (/heatwave|extreme heat|heat|feel hot|very hot/.test(lower)) intent = 'heat';
else if (/drought|water shortage|water scarcity/.test(lower)) intent = 'drought';

let requested_stakeholder = 'general_public';
if (/farmer|farm|crop|livestock|agriculture/.test(lower)) requested_stakeholder = 'farmers';
else if (/public|resident|people|instead/.test(lower)) requested_stakeholder = 'general_public';
else if (/grid operator|utility|electricity operator/.test(lower)) requested_stakeholder = 'grid_operators';
else if (/emergency|rescue|disaster authority/.test(lower)) requested_stakeholder = 'emergency_authorities';
else if (/logistics|delivery|transport operator|supply chain/.test(lower)) requested_stakeholder = 'logistics_operators';
else if (/local government|municipality|council|government/.test(lower)) requested_stakeholder = 'local_government';
else if (memory.last_stakeholder) requested_stakeholder = memory.last_stakeholder;

let region_query = explicitRegion || extractRegion(message);
let use_saved_region = false;
let used_awaiting_region = false;
let restored_pending_intent = '';
let pending_intent = '';

if (memory.awaiting_region && !explicitRegion && isLocationOnlyCandidate(message)) {
  region_query = cleanRegion(message);
  restored_pending_intent = memory.pending_intent || memory.last_pending_intent || pendingFromIntent(memory.last_intent || 'general_threats', message);
  intent = intentFromPending(restored_pending_intent) || intent;
  used_awaiting_region = true;
}

if (!region_query && memory.last_region && /\b(this area|here|there|same area|previous|that|why|happening|what should|public do|farmers do|instead|dangerous|serious)\b/i.test(classificationMessage)) {
  region_query = memory.last_region;
  use_saved_region = true;
}

// Severity follow-up: reuse the saved assessment instead of re-geocoding.
const severityFollowupRe = /\b(how serious|how bad|how severe|how dangerous|is (?:this|it) dangerous|risk level|how risky|should (?:i|we) be worried|how concerning)\b/i;
if (severityFollowupRe.test(classificationMessage) && !explicitRegion && recentAssessment && use_saved_region) {
  intent = 'severity_followup';
}

// Evidence follow-up: reuse the saved assessment's evidence instead of re-fetching.
// When the user asks for evidence with no new region, and a recent assessment
// with a saved region exists, answer from memory (no geocoding/APIs/agents).
if (intent === 'evidence' && !explicitRegion && !region_query && recentAssessment && memory.active_region && memory.last_assessment) {
  intent = 'evidence_followup';
  region_query = memory.active_region;
  use_saved_region = true;
}

const asksEvidence = /\b(evidence|reports?|news|sources?|why|cause|causes|full report|happening)\b/i.test(classificationMessage);
const actions_requested = intent === 'actions';
const isGreeting = intent === 'greeting' || intent === 'help';
const personalWeatherWithoutRegion = !region_query && /\b(i\s*(feel|am|'m|need|have)\s*(very\s*)?(hot|cold|freezing|overheated)|weather\s+feels\s+(freezing|cold|hot)|feeling\s+(very\s*)?(hot|cold|freezing)|too\s+(hot|cold))\b/i.test(classificationMessage);
const vagueThreatWithoutRegion = !region_query && /\b(check|current|what|any|show|tell)\b/i.test(classificationMessage) && /\b(threats?|risks?|danger|disaster|alerts?)\b/i.test(classificationMessage);
const personalConcernWithoutRegion = !region_query && /\b(i\s*(feel|am|'m|need|have|see|saw|smell|hear|noticed|worry|worried|scared|concerned)|my\s+(area|home|farm|road|village|city|family|crops|livestock)|there\s+is|it\s+is|it's)\b/i.test(classificationMessage) && !/\b(hello|hi|hey|help|what can you do)\b/i.test(classificationMessage);
const missingRegion = !region_query && !isGreeting && !asksRegionAccess;
const vagueConversational = /\b(i feel|i am|i'm|very hot|too hot|freezing|why|happening|instead|what about|what should)\b/i.test(classificationMessage) && !explicitRegion;
const canUseCachedAction = recentAssessment && actions_requested && region_query && use_saved_region;
const canUseCachedEvidence = recentAssessment && (intent === 'evidence' || intent === 'evidence_followup') && region_query && use_saved_region;
const canUseCachedSeverity = recentAssessment && intent === 'severity_followup' && region_query && use_saved_region;

if (used_awaiting_region) pending_intent = restored_pending_intent;
else if (personalWeatherWithoutRegion) pending_intent = 'weather_heat_check';
else if (vagueThreatWithoutRegion || (missingRegion && !personalWeatherWithoutRegion && !isGreeting)) pending_intent = pendingFromIntent(intent, message);

let direct_response = null;
if (asksRegionAccess) {
  direct_response = {
    ok: true,
    response_kind: 'REGION_ACCESS',
    overall_threat_level: 'NONE',
    correlation_status: 'NOT_APPLICABLE',
    regional_summary: 'CrisisLens supports the Asian regions supplied by the WIaaS Region panel.',
  };
} else if (intent === 'greeting') {
  direct_response = {
    ok: true,
    response_kind: 'GREETING',
    overall_threat_level: 'NONE',
    correlation_status: 'NOT_APPLICABLE',
    regional_summary: "Hello, I'm WIaaS CrisisLens. Ask me about weather, floods, wildfire risk, disaster alerts, regional threats, or actions for farmers, authorities, logistics teams, and the public.",
  };
} else if (intent === 'help') {
  direct_response = {
    ok: true,
    response_kind: 'HELP',
    overall_threat_level: 'NONE',
    correlation_status: 'NOT_APPLICABLE',
    regional_summary: 'I can check current weather, flood or wildfire risk, GDACS disaster alerts, regional reports, and practical actions for specific stakeholders. Tell me a city, state, province, or country.',
  };
} else if (missingRegion || personalConcernWithoutRegion) {
  direct_response = {
    ok: true,
    response_kind: 'REGION_REQUIRED',
    region: '',
    overall_threat_level: 'NONE',
    correlation_status: 'NOT_APPLICABLE',
    regional_summary: personalWeatherWithoutRegion
      ? 'I’m sorry you’re dealing with that. Which city, region, or country are you in? I’ll check the current weather and heat or cold risk there.'
      : (personalConcernWithoutRegion
        ? 'I’m sorry you’re dealing with that. I can check nearby weather, disaster alerts, and regional threat signals for you. Where are you located?'
        : 'Which city, state, province, or country should I check?'),
    awaiting_region: true,
    pending_intent,
  };
}

return [{
  json: {
    valid: Boolean(message || explicitRegion),
    message,
    region_query,
    explicit_region: explicitRegion,
    intent,
    pending_intent,
    restored_pending_intent,
    selected_route: used_awaiting_region ? (restored_pending_intent || pending_intent) : (intent === 'weather' || intent === 'heat' ? 'weather_heat_check' : intent),
    requested_stakeholder,
    actions_requested,
    asks_evidence: asksEvidence,
    session_id: sessionId,
    user_id: String(input.user_id ?? input.userId ?? 'anonymous'),
    source_channel,
    api_only: true,
    backend_used: false,
    needs_geocode: !hasSuppliedCoordinates && !direct_response && !canUseCachedAction && !canUseCachedEvidence && !canUseCachedSeverity,
    direct_response,
    needs_conversation_agent: Boolean(!direct_response && (vagueConversational || missingRegion || personalConcernWithoutRegion) && !(region_query && ['weather', 'heat', 'general_threats', 'actions', 'evidence'].includes(intent))),
    conversation_memory: {
      last_region: memory.last_region || memory.active_region || '',
      active_region: memory.active_region || memory.last_region || '',
      region_key: memory.region_key || '',
      latitude: memory.latitude ?? null,
      longitude: memory.longitude ?? null,
      last_intent: memory.last_intent || '',
      pending_intent: memory.pending_intent || '',
      last_pending_intent: memory.last_pending_intent || '',
      last_stakeholder: memory.last_stakeholder || '',
      last_threat_level: memory.last_threat_level || '',
      last_assessment: memory.last_assessment || null,
      last_threats: Array.isArray(memory.last_threats) ? memory.last_threats : [],
      awaiting_region: Boolean(memory.awaiting_region),
      updated_at: memory.updated_at || '',
      has_recent_assessment: Boolean(recentAssessment),
      memory_load_ok: memoryLoad.ok,
      memory_load_error: memoryLoad.error,
    },
    use_saved_region,
    used_awaiting_region,
    cached_followup: canUseCachedAction || canUseCachedEvidence || canUseCachedSeverity,
    cached_severity: canUseCachedSeverity,
    cached_evidence: canUseCachedEvidence,
    cached_assessment: canUseCachedAction || canUseCachedEvidence || canUseCachedSeverity ? memory.last_assessment : null,
    schema_version: input.schema_version || 'wiaas.asia.chat.v1',
    request_kind: input.request_kind || 'standard_query',
    execution_mode: input.execution_mode || 'efficient',
    response_style: input.response_style || 'structured',
    max_response_words: Number(input.max_response_words) || 300,
    token_strategy: input.token_strategy || 'deterministic_and_cached_first',
    response_language: String(input.response_language || 'en').toLowerCase().startsWith('ur') ? 'ur' : 'en',
    routing_query: String(input.routing_query || ''),
    accessible_region_names: accessibleRegionNames,
    turn_index: Number(input.turn_index) || 1,
    repeated_question_count: Number(input.repeated_question_count) || 0,
    response_variant: Number(input.response_variant) || 0,
    recent_user_messages: Array.isArray(input.recent_user_messages) ? input.recent_user_messages.slice(-5) : [],
    region_key: String(input.region_key || suppliedContext.key || ''),
    region_name: String(input.region_name || suppliedContext.name || explicitRegion || ''),
    region_context: { ...suppliedContext, key: input.region_key || suppliedContext.key || '', name: input.region_name || suppliedContext.name || explicitRegion || '', city: input.city || suppliedContext.city || '', province: input.province || suppliedContext.province || '', country: input.country || suppliedContext.country || '', country_code: input.country_code || suppliedContext.country_code || '', asian_subregion: input.asian_subregion || suppliedContext.asian_subregion || 'Asia', latitude: hasSuppliedCoordinates ? suppliedLatitude : null, longitude: hasSuppliedCoordinates ? suppliedLongitude : null, timezone: input.timezone || suppliedContext.timezone || '' },
    supplied_telemetry: input.telemetry || null,
    supplied_climate_matrix: input.climate_matrix || null,
    supplied_ledger: input.ledger || input.synthetic_resource_ledger || null,
  }
}];

const request = $('Parse User Request').item.json;
const geocode = $json ?? {};
const queryRaw = String(request.region_query ?? '').trim();
const query = queryRaw.toLowerCase();

function isWeatherRoute(req) {
  return ['weather', 'heat'].includes(req.intent) || ['weather_heat_check', 'weather_temperature_check', 'weather_check', 'heat_check', 'cold_check'].includes(String(req.pending_intent || req.restored_pending_intent || req.selected_route || '').toLowerCase());
}

function planFor(req, geocodeOk) {
  const noApi = Boolean(req.direct_response) || !geocodeOk;
  const weatherOnly = isWeatherRoute(req);
  const evidence = Boolean(req.asks_evidence) || req.intent === 'evidence';
  const disaster = ['flood', 'earthquake', 'storm'].includes(req.intent);
  const wildfire = req.intent === 'wildfire';
  const actionOnly = req.intent === 'actions' && req.cached_followup;
  return {
    selected_route: weatherOnly ? 'weather_heat_check' : (req.intent === 'general_threats' ? 'threat_assessment' : req.intent),
    call_weather: !noApi && !actionOnly && (weatherOnly || wildfire || disaster || req.intent === 'general_threats' || ['drought', 'evidence', 'actions'].includes(req.intent)),
    call_firms: false,
    call_gdacs: !noApi && !weatherOnly && !actionOnly && (disaster || req.intent === 'general_threats' || req.intent === 'evidence' || req.intent === 'actions'),
    call_gdelt: !noApi && !weatherOnly && evidence,
    run_osint: !noApi && !weatherOnly && !actionOnly,
    run_action: Boolean(req.actions_requested) && !Boolean(req.cached_followup) && !weatherOnly,
    firms_reason: 'MAP_KEY_NOT_CONFIGURED',
  };
}

const adminFallbacks = {};

function slug(value) {
  return String(value || '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
}

function newsQueryFor(region, req) {
  const threatTermsByIntent = {
    wildfire: '(wildfire OR "forest fire" OR "active fire")',
    flood: '(flood OR flooding OR "heavy rain")',
    earthquake: '(earthquake OR seismic)',
    storm: '(storm OR cyclone OR hurricane OR typhoon)',
    heat: '(heatwave OR "extreme heat" OR temperature)',
    drought: '(drought OR "water shortage")',
  };
  const threatTerms = threatTermsByIntent[req.intent] ?? '(wildfire OR flood OR storm OR heatwave OR drought OR earthquake)';
  const places = [region.name, region.admin1, region.country].filter(Boolean);
  return (places.map((v) => '"' + String(v).replace(/"/g, '') + '"').join(' ') + ' ' + threatTerms).trim();
}

function outputForRegion(region, geocode_source = 'open_meteo') {
  const lat = Number(region.latitude);
  const lon = Number(region.longitude);
  const bbox = region.bbox || { north: +(lat + 1.5).toFixed(4), south: +(lat - 1.5).toFixed(4), east: +(lon + 1.5).toFixed(4), west: +(lon - 1.5).toFixed(4) };
  const api_plan = planFor(request, true);
  const display = request.region_name || [...new Set([region.name, region.admin1, region.country].filter(Boolean))].join(', ');
  return {
    ...request,
    geocode_ok: true,
    geocode_source,
    selected_route: api_plan.selected_route,
    restored_pending_intent: request.restored_pending_intent || request.pending_intent || '',
    active_region: display,
    region_key: request.region_key || slug([region.country_code || region.country, region.admin1, region.name].filter(Boolean).join('_')),
    region: {
      name: region.name,
      country: region.country ?? '',
      country_code: region.country_code ?? '',
      admin1: region.admin1 ?? '',
      admin2: region.admin2 ?? '',
      latitude: lat,
      longitude: lon,
      timezone: region.timezone ?? 'auto',
    },
    latitude: lat,
    longitude: lon,
    north: bbox.north,
    south: bbox.south,
    east: bbox.east,
    west: bbox.west,
    news_query: newsQueryFor(region, request),
    api_plan,
  };
}

const supplied = request.region_context && typeof request.region_context === 'object' ? request.region_context : {};
const suppliedLat = Number(supplied.latitude ?? request.latitude);
const suppliedLon = Number(supplied.longitude ?? request.longitude);
const suppliedInsideAsia = Number.isFinite(suppliedLat) && Number.isFinite(suppliedLon) && suppliedLat >= -12 && suppliedLat <= 82 && suppliedLon >= 25 && suppliedLon <= 180;
if (!request.direct_response && suppliedInsideAsia) {
  return [{ json: outputForRegion({
    name: supplied.city || supplied.name || request.region_name || supplied.country || 'Selected Asian region',
    admin1: supplied.province || '',
    country: supplied.country || '',
    country_code: supplied.country_code || '',
    latitude: suppliedLat,
    longitude: suppliedLon,
    timezone: supplied.timezone || request.timezone || 'auto',
  }, 'wiaas_region_context') }];
}

if (request.direct_response) {
  return [{ json: { ...request, geocode_ok: false, api_plan: planFor(request, false) } }];
}

const fallback = adminFallbacks[query];
if (fallback) return [{ json: outputForRegion(fallback, 'region_registry') }];

const ASIA_CODES = new Set(['AF','AM','AZ','BH','BD','BT','BN','KH','CN','CY','GE','IN','ID','IR','IQ','IL','JP','JO','KZ','KW','KG','LA','LB','MY','MV','MN','MM','NP','KP','OM','PK','PS','PH','QA','SA','SG','KR','LK','SY','TW','TJ','TH','TL','TR','TM','AE','UZ','VN','YE']);
const hits = (Array.isArray(geocode.results) ? geocode.results : []).filter((item) => ASIA_CODES.has(String(item.country_code || '').toUpperCase()));
function score(hit) {
  const country = String(hit.country ?? '').toLowerCase();
  const admin1 = String(hit.admin1 ?? '').toLowerCase();
  const name = String(hit.name ?? '').toLowerCase();
  let value = 0;
  if (country && query.includes(country)) value += 10;
  if (admin1 && query.includes(admin1)) value += 8;
  if (name && query.includes(name)) value += 6;
  if (name === query) value += 6;
  if (hit.feature_code && /adm/i.test(String(hit.feature_code))) value += 3;
  value += Math.min(Number(hit.population ?? 0) / 1000000, 3);
  return value;
}

const hit = hits
  .filter((h) => Number.isFinite(Number(h.latitude)) && Number.isFinite(Number(h.longitude)))
  .sort((a, b) => score(b) - score(a))[0] ?? null;

if (!hit) {
  const keepPending = request.pending_intent || request.restored_pending_intent || 'general_threats';
  return [{
    json: {
      ...request,
      geocode_ok: false,
      selected_route: 'ask_valid_region',
      direct_response: {
        ok: false,
        error: 'REGION_NOT_FOUND',
        response_kind: 'REGION_REQUIRED',
        region: queryRaw,
        regional_summary: 'I could not find that location. Please send a valid city, country, province, state, or supported region and I’ll continue the same check.',
        awaiting_region: true,
        pending_intent: keepPending,
      },
      api_plan: planFor(request, false),
    }
  }];
}

return [{ json: outputForRegion(hit) }];

const context = $('Prepare API Context').item.json;
const inputs = $input.all().map((i) => i.json);
const byType = Object.fromEntries(inputs.map((i) => [i.source_type, i]));

function arrMax(values) {
  const nums = (values || []).map(Number).filter(Number.isFinite);
  return nums.length ? Math.max(...nums) : null;
}
function cleanText(value, max = 180) {
  return String(value || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
}
function decodeXml(value = '') {
  return cleanText(String(value).replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
    .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
    .replace(/&#39;/g, "'").replace(/&quot;/g, '"'), 240);
}
function extractTag(block, tag) {
  const match = String(block).match(new RegExp('<' + tag + '[^>]*>([\\\\s\\\\S]*?)<\\\\/' + tag + '>', 'i'));
  return match ? decodeXml(match[1]) : '';
}
function uniqueBy(items, keyFn) {
  const seen = new Set();
  return items.filter((item) => {
    const key = String(keyFn(item) || '').toLowerCase().trim();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}
function csvToObjects(csv, limit = 3) {
  if (typeof csv !== 'string' || !csv.includes('\n')) return [];
  const rows = csv.trim().split(/\r?\n/).filter(Boolean);
  if (rows.length < 2 || !rows[0].toLowerCase().includes('latitude')) return [];
  const headers = rows[0].split(',').map((h) => h.trim());
  return rows.slice(1, limit + 1).map((line) => {
    const cols = line.split(',').map((c) => c.trim());
    return Object.fromEntries(headers.map((h, idx) => [h, cols[idx] ?? '']));
  });
}

const direct = context.direct_response;
const weatherRaw = byType.weather?.data ?? {};
const hourly = weatherRaw.hourly ?? {};
const current = weatherRaw.current ?? {};
const weather_summary = {
  temperature: Number.isFinite(Number(current.temperature_2m)) ? Number(current.temperature_2m) : null,
  humidity: Number.isFinite(Number(current.relative_humidity_2m)) ? Number(current.relative_humidity_2m) : null,
  apparent_temperature: Number.isFinite(Number(current.apparent_temperature)) ? Number(current.apparent_temperature) : null,
  current_rain: Number.isFinite(Number(current.rain)) ? Number(current.rain) : 0,
  current_precipitation: Number.isFinite(Number(current.precipitation)) ? Number(current.precipitation) : 0,
  max_precipitation_probability_24h: arrMax((hourly.precipitation_probability || []).slice(0, 24)),
  max_wind_speed_24h: arrMax((hourly.wind_speed_10m || []).slice(0, 24)),
  max_wind_gust_24h: arrMax((hourly.wind_gusts_10m || []).slice(0, 24)),
  max_temperature_24h: arrMax((hourly.temperature_2m || []).slice(0, 24)),
};

const fires = byType.fire?.ok ? csvToObjects(byType.fire.data, 3).map((r) => ({
  latitude: Number(r.latitude),
  longitude: Number(r.longitude),
  confidence: r.confidence || '',
  acquisition_date: r.acq_date || '',
  short_finding: 'Satellite fire detection from NASA FIRMS',
})).filter((x) => Number.isFinite(x.latitude) && Number.isFinite(x.longitude)).slice(0, 3) : [];

const regionTerms = [context.region?.name, context.region?.admin1, context.region?.country, context.region_query].filter(Boolean).map((v) => String(v).toLowerCase());
const gdacsText = typeof byType.disaster?.data === 'string' ? byType.disaster.data : String(byType.disaster?.data?.data ?? '');
const disaster_alerts = uniqueBy((gdacsText.match(/<item[\s\S]*?<\/item>/gi) || []).map((block) => {
  const title = extractTag(block, 'title');
  const description = extractTag(block, 'description');
  return {
    title: cleanText(title, 120),
    disaster_type: cleanText(extractTag(block, 'gdacs:eventtype') || title.split(' ')[0], 40),
    alert_level: cleanText(extractTag(block, 'gdacs:alertlevel') || extractTag(block, 'gdacs:severity'), 40),
    published_at: cleanText(extractTag(block, 'pubDate'), 80),
    short_finding: cleanText(description || title, 160),
