}).filter((item) => {
  const haystack = [item.title, item.short_finding].join(' ').toLowerCase();
  return regionTerms.some((term) => term.length > 1 && haystack.includes(term));
}), (a) => a.url || a.title).slice(0, 3);

const articles = Array.isArray(byType.news?.data?.articles) ? byType.news.data.articles : [];
const regional_news = uniqueBy(articles.map((a) => ({
  title: cleanText(a.title, 130),
  source_domain: cleanText(a.domain, 60),
  published_at: cleanText(a.seendate || a.date, 60),
  url: a.url || '',
  short_finding: cleanText(a.title, 150),
})), (a) => a.url || a.title).slice(0, 3);

const preliminary_threats = [];
if (Number(weather_summary.temperature) >= 40) preliminary_threats.push({ type: 'extreme_heat', severity: weather_summary.temperature >= 45 ? 'HIGH' : 'MEDIUM', short_finding: 'Temperature is ' + weather_summary.temperature + ' C' });
if (Number(weather_summary.max_wind_gust_24h) >= 60) preliminary_threats.push({ type: 'strong_wind', severity: weather_summary.max_wind_gust_24h >= 90 ? 'HIGH' : 'MEDIUM', short_finding: 'Max wind gust is ' + weather_summary.max_wind_gust_24h + ' km/h' });
if (Number(weather_summary.current_rain) >= 20 || Number(weather_summary.current_precipitation) >= 20) preliminary_threats.push({ type: 'heavy_rainfall', severity: 'MEDIUM', short_finding: 'Observed current rainfall is ' + (Number(weather_summary.current_rain) || Number(weather_summary.current_precipitation) || 0) + ' mm' });
else if (Number(weather_summary.max_precipitation_probability_24h) >= 70) preliminary_threats.push({ type: 'elevated_precipitation_probability', severity: 'LOW', short_finding: 'Forecast precipitation probability up to ' + (weather_summary.max_precipitation_probability_24h ?? 'unknown') + '% in the next 24h; no heavy rainfall currently observed' });
if (fires.length) preliminary_threats.push({ type: 'active_fire_detection', severity: fires.length >= 3 ? 'HIGH' : 'MEDIUM', short_finding: fires.length + ' fire detections available' });
for (const alert of disaster_alerts) preliminary_threats.push({ type: 'gdacs_disaster_alert', severity: /red|orange/i.test(alert.alert_level) ? 'HIGH' : 'MEDIUM', short_finding: alert.title });

