const osintRegionName = [context.region?.name, context.region?.admin1, context.region?.country].filter(Boolean).join(', ') || context.region_query || context.active_region || '';
const OSINT_EVIDENCE_LIMIT = 5;
const gdacsCompact = disaster_alerts.slice(0, OSINT_EVIDENCE_LIMIT).map((a) => ({ title: a.title, alert_level: a.alert_level, disaster_type: a.disaster_type }));
const newsCompact = regional_news.slice(0, Math.max(0, OSINT_EVIDENCE_LIMIT - gdacsCompact.length)).map((a) => ({ title: a.title, source: a.source_domain }));
const osint_input = {
  region: osintRegionName,
  temperature: n0(weather_summary.temperature),
  feels_like: n0(weather_summary.apparent_temperature),
  humidity: n0(weather_summary.humidity),
  current_precipitation: n0(weather_summary.current_precipitation),
  precipitation_probability_24h: n0(weather_summary.max_precipitation_probability_24h),
  max_wind_gust_24h: n0(weather_summary.max_wind_gust_24h),
  gdacs_alerts: gdacsCompact,
  relevant_news: newsCompact,
};

const source_status = inputs.map((i) => ({
  source: i.source_name,
  type: i.source_type,
  ok: Boolean(i.ok),
  reason: i.ok ? null : (i.reason || i.error || 'NOT_AVAILABLE'),
}));
const selected = source_status.filter((s) => !['NOT_SELECTED', 'NOT_NEEDED'].includes(String(s.reason)));
const selectedOk = selected.filter((s) => s.ok);
const apiUnavailable = !direct && selected.length > 0 && selectedOk.length === 0;
const hasEvidence = preliminary_threats.length > 0 || disaster_alerts.length > 0 || regional_news.length > 0 || fires.length > 0;
const weatherOnly = context.api_plan?.selected_route === 'weather_heat_check' || context.intent === 'weather' || ['weather_heat_check', 'weather_temperature_check', 'weather_check', 'heat_check', 'cold_check'].includes(String(context.pending_intent || context.restored_pending_intent || context.selected_route || '').toLowerCase());
const run_osint = Boolean(context.api_plan?.run_osint && hasEvidence && !apiUnavailable);
const run_action = Boolean(run_osint && context.actions_requested);

return [{
  json: {
    direct_response: direct || null,
    response_kind: direct?.response_kind || (apiUnavailable ? 'API_UNAVAILABLE' : weatherOnly ? 'WEATHER_ONLY' : hasEvidence ? 'THREAT_EVIDENCE' : 'NO_MEASURABLE_THREAT'),
    region: context.region ?? { name: context.region_query },
    intent: context.intent,
    requested_stakeholder: context.requested_stakeholder,
    source_channel: context.source_channel,
    session_id: context.session_id,
    active_region: context.active_region,
    region_key: context.region_key,
    latitude: context.latitude,
    longitude: context.longitude,
    selected_route: context.api_plan?.selected_route || context.selected_route,
    pending_intent: context.pending_intent || '',
    restored_pending_intent: context.restored_pending_intent || '',
    used_awaiting_region: Boolean(context.used_awaiting_region),
    conversation_memory_before: context.conversation_memory || {},
    api_plan: context.api_plan,
    actions_requested: context.actions_requested,
    weather_summary,
    fire_detections: fires,
    disaster_alerts,
    regional_news,
    preliminary_threats: preliminary_threats.slice(0, 5),
    osint_input,
    source_status,
    ai_decision: { run_osint, run_action },
  }
}];

