function parseJsonSafe(value, fallback) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  const fence = String.fromCharCode(96) + String.fromCharCode(96) + String.fromCharCode(96);
  const text = String(value ?? '').trim()
    .replace(new RegExp('^' + fence + 'json\\s*', 'i'), '')
    .replace(new RegExp('^' + fence + '\\s*', 'i'), '')
    .replace(new RegExp(fence + '$', 'i'), '')
    .trim();
  try { return JSON.parse(text); } catch {}
  const start = text.indexOf('{'), end = text.lastIndexOf('}');
  if (start >= 0 && end > start) { try { return JSON.parse(text.slice(start, end + 1)); } catch {} }
  return fallback;
}
function getNodeJson(name) { try { return $(name).item.json; } catch { return null; } }
const normalized = getNodeJson('Normalize API Data') || $json;
const regionName = [normalized.region?.name, normalized.region?.admin1, normalized.region?.country].filter(Boolean).join(', ');
function cleanRegion(value){ const parts=String(value||'').split(',').map((p)=>p.trim()).filter(Boolean); const out=[]; for(const p of parts){ const pl=p.toLowerCase(); if(out.some((q)=>q.toLowerCase()===pl))continue; const redundant=parts.some((o)=>{ const ol=o.toLowerCase(); if(o===p||ol.length<=pl.length)return false; return (' '+ol+' ').indexOf(' '+pl+' ')!==-1; }); if(redundant)continue; out.push(p); } return out.join(', '); }
const regionDisplay = cleanRegion(regionName);
const direct = normalized.direct_response;
if (direct) {
  return [{ json: { ...direct, system: 'WIaaS CrisisLens', api_only: true, backend_used: false, source_channel: normalized.source_channel || getNodeJson('Parse User Request')?.source_channel || 'webhook', session_id: getNodeJson('Parse User Request')?.session_id || normalized.session_id, selected_route: normalized.selected_route || direct.pending_intent || 'direct_response', restored_pending_intent: normalized.restored_pending_intent || normalized.pending_intent || direct.pending_intent || '', api_plan: normalized.api_plan || {}, conversation_memory_before: normalized.conversation_memory_before || getNodeJson('Parse User Request')?.conversation_memory || {}, conversation_agent_used: Boolean(getNodeJson('Apply Conversation Decision')?.conversation_agent_used) } }];
}

// Rain wording safety: never call precipitation probability "heavy rain" unless
// rainfall amount/intensity/accumulation or an official warning supports it.
const _normStr = JSON.stringify(normalized || {});
const hasRainEvidence = /\d+(?:\.\d+)?\s*mm|rainfall of|accumulat|red alert|orange alert|official warning|severe weather warning|flood warning/i.test(_normStr);
// Severe-weather wording is only allowed when an official alert or confirmed
// severe signal supports it. Otherwise neutralize "severe weather system" style
// phrasing that would otherwise be inferred from precipitation probability alone.
const hasSevereEvidence = /red alert|orange alert|official warning|severe weather warning|flood warning|cyclone warning|storm warning|gale warning|tornado warning|hurricane warning|evacuat/i.test(_normStr);
function scrubSevere(text){
  let t = String(text || '');
  if (hasSevereEvidence) return t;
  t = t.replace(/approaching severe weather system/gi, 'an elevated chance of precipitation with moderate wind gusts');
  t = t.replace(/approaching storm system/gi, 'an elevated chance of precipitation with moderate wind gusts');
  t = t.replace(/(?:potential|possible|approaching|imminent|expected|developing|likely) severe weather/gi, 'an elevated chance of precipitation with moderate wind gusts');
  t = t.replace(/severe weather (?:system|is )?(?:approaching|imminent|expected|developing|likely)/gi, 'an elevated chance of precipitation with moderate wind gusts');
  t = t.replace(/(?:possible |potential |approaching )?(?:approaching )?storms?(?: system)?/gi, 'unsettled weather');
  t = t.replace(/severe weather system/gi, 'unsettled weather');
  t = t.replace(/severe (?:thunder)?storm(?:s)?/gi, 'unsettled weather');
  t = t.replace(/severe weather/gi, 'unsettled weather');
  return t;
}
function scrubRain(text){
  let t = String(text || '');
  if (hasRainEvidence) return t;
  t = t.replace(/imminent heavy rainfall/gi, 'a high chance of precipitation');
  t = t.replace(/imminent heavy rain/gi, 'a high chance of precipitation');
  t = t.replace(/imminent heavy precipitation/gi, 'a high chance of precipitation');
  t = t.replace(/severe rainfall/gi, 'a high chance of precipitation');
  t = t.replace(/heavy rainfall is (?:expected|forecast|likely|imminent)/gi, 'a high probability of precipitation is forecast, but heavy rainfall is not currently confirmed');
  t = t.replace(/heavy rain is (?:expected|forecast|likely|imminent)/gi, 'a high probability of precipitation is forecast, but heavy rainfall is not currently confirmed');
  t = t.replace(/heavy rainfall/gi, 'precipitation');
  t = t.replace(/heavy rain/gi, 'precipitation');
  return t;
}
function scrubRainItem(x){ if (x && typeof x === 'object') { const o = { ...x }; for (const k of Object.keys(o)) { if (typeof o[k] === 'string') o[k] = scrubRain(o[k]); } return o; } return scrubRain(x); }

const sourceOk = (normalized.source_status || []).filter((s) => s.ok).map((s) => s.source);
const sourceGaps = (normalized.source_status || []).filter((s) => !s.ok && !['NOT_SELECTED', 'NOT_NEEDED'].includes(String(s.reason))).map((s) => s.source + ':' + s.reason);
const fireRelevant = String(normalized.intent || '').toLowerCase() === 'wildfire';
const newsRelevant = Boolean(normalized.api_plan?.call_gdelt);
function gapText(x){ if (x && typeof x === 'object') return String(x.description || x.detail || x.gap || x.text || x.title || x.message || x.name || ''); return String(x); }
function evidenceText(x){ if (x && typeof x === 'object') return String(x.detail || x.description || x.short_finding || x.title || x.text || x.gap || ''); return String(x); }
function scrubEvidenceList(list){ return (Array.isArray(list) ? list : []).filter((x) => { const s = evidenceText(x).toLowerCase(); if (!newsRelevant && /(news|gdelt|media|feed)/.test(s) && /(unavailable|not configured|inactive|not selected|limited|narrow|missing|reduced|no coverage|lack)/.test(s)) return false; if (!fireRelevant && /(nasa|firms|fire monitoring|map[_ ]?key|satellite fire)/.test(s)) return false; return evidenceText(x).trim().length > 0; }); }
function splitSentences(text){ const s = String(text || ''); const out = []; let cur = ''; for (let i = 0; i < s.length; i++) { const ch = s[i]; cur += ch; if (ch === '.' || ch === '!' || ch === '?') { const prev = s[i-1], next = s[i+1]; if (ch === '.' && /\d/.test(prev || '') && /\d/.test(next || '')) continue; if (next === undefined || /\s/.test(next)) { if (cur.trim()) out.push(cur.trim()); cur = ''; } } } if (cur.trim()) out.push(cur.trim()); return out.length ? out : [String(text || '')]; }
function scrubSummary(text){ const parts = splitSentences(text); const kept = parts.filter((s) => { const low = s.toLowerCase(); if (!fireRelevant && /(nasa|firms|fire monitoring|fire detection|map[_ ]?key|satellite fire)/.test(low)) return false; if (!newsRelevant && /(news|gdelt|media|feed)/.test(low) && /(unavailable|not configured|inactive|not selected|limited|narrow|missing|no )/.test(low)) return false; if (/not[_ ]?selected|unconfigured|not configured|inactive news feed|map[_ ]?key/.test(low)) return false; return s.trim().length > 0; }); return kept.join(' ').replace(/ +/g, ' ').trim(); }
function naturalizeGap(g) { const src = String(g).split(':')[0].trim(); const low = src.toLowerCase(); if (low.includes('firms')) return 'Satellite fire-detection data was unavailable for this area'; if (low.includes('gdelt')) return 'Regional news signals were limited or unavailable'; if (low.includes('gdacs')) return 'Disaster-alert data was temporarily unavailable'; if (low.includes('meteo')) return 'Weather data was temporarily unavailable'; return src + ' data was unavailable'; }
function gapIsRelevant(g) { const s = String(g).toLowerCase(); if (/firms|fire|map[_ ]?key|nasa/.test(s) && !fireRelevant) return false; return true; }
function sanitizeGapList(list) { return (Array.isArray(list) ? list : []).map(gapText).filter((x) => { const s = x.toLowerCase(); if (/firms|fire monitoring|map[_ ]?key|nasa/.test(s) && !fireRelevant) return false; if (/news|gdelt|media|feed/.test(s) && !newsRelevant) return false; if (/not[_ ]?selected|not[_ ]?needed|unconfigured|not configured|inactive news feed|news feed/.test(s)) return false; return Boolean(x.trim()); }); }
const userGaps = sourceGaps.filter(gapIsRelevant).map(naturalizeGap);
if (normalized.response_kind === 'API_UNAVAILABLE') {
  return [{ json: { ok: false, error: 'API_UNAVAILABLE', system: 'WIaaS CrisisLens', region: regionName, overall_threat_level: 'API_UNAVAILABLE', correlation_status: 'INSUFFICIENT_EVIDENCE', regional_summary: 'Selected external sources were unavailable, so no threat level was assigned.', source_status: { successful: sourceOk, failed_or_unconfigured: userGaps }, source_channel: normalized.source_channel, session_id: normalized.session_id, selected_route: normalized.selected_route } }];
}

const weather = normalized.weather_summary || {};
function num(value) {
  return Number.isFinite(Number(value)) ? Number(value) : null;
}
function weatherCondition(w) {
  if (num(w.current_precipitation) > 0 || num(w.current_rain) > 0) return 'rain or precipitation is being reported';
  if (num(w.max_wind_speed_24h) >= 35) return 'wind may be noticeable';
  return 'no major precipitation is showing in the current reading';
}
function heatRisk(w) {
  const apparent = num(w.apparent_temperature);
  const temp = num(w.temperature);
  const t = apparent ?? temp;
  if (t === null) return 'I do not have enough temperature data to judge heat or cold stress.';
  if (t >= 45) return 'This is dangerous heat. Stay out of direct sun if you can, drink water, and seek medical help for confusion, fainting, chest pain, or worsening symptoms.';
  if (t >= 40) return 'This is very high heat. Reduce outdoor activity, drink water often, and move to shade or a cooler place.';
  if (t >= 35) return 'This can feel stressful, especially during activity or high humidity. Take breaks, hydrate, and cool down.';
  if (t <= 0) return 'This is freezing or near-freezing weather. Keep warm, limit exposure, and watch for numbness or shivering.';
  if (t <= 7) return 'This is cold enough to be uncomfortable with exposure. Keep warm and dry.';
  return 'The current temperature does not indicate severe heat or cold stress, but your symptoms still matter. Rest, hydrate, and seek help if you feel unwell.';
}

if (normalized.response_kind === 'WEATHER_ONLY') {
  const temp = weather.temperature ?? 'unknown';
  const apparent = weather.apparent_temperature ?? 'unknown';
  const humidity = weather.humidity ?? 'unknown';
  // Neutral, non-symptom conditions description.
  function neutralConditions(w) {
    if (num(w.current_precipitation) > 0 || num(w.current_rain) > 0) return 'precipitation is currently being reported';
    return 'no significant precipitation is currently reported';
  }
  // Wind: prefer current wind speed, fall back to max forecast wind.
  const windVal = num(weather.wind_speed) != null ? num(weather.wind_speed) : (num(weather.current_wind_speed) != null ? num(weather.current_wind_speed) : num(weather.max_wind_speed_24h));
  const windClause = windVal != null
    ? 'Winds are around ' + windVal + ' km/h'
    : 'Wind data is not available';
  // Weather-only region display: city + country (drop intermediate admin levels).
  const weatherRegion = cleanRegion([normalized.region?.name, normalized.region?.country].filter(Boolean).join(', ')) || regionDisplay || (normalized.region?.name || 'that location');
  // Only include symptom-focused guidance when the user explicitly reports feeling unwell.
  const userMsg = String(getNodeJson('Parse User Request')?.message || '').toLowerCase();
