function parseJsonSafe(value, fallback) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  const fence = String.fromCharCode(96) + String.fromCharCode(96) + String.fromCharCode(96);
  const text = String(value ?? '').trim()
    .replace(new RegExp('^' + fence + 'json\\s*', 'i'), '')
    .replace(new RegExp('^' + fence + '\\s*', 'i'), '')
    .replace(new RegExp(fence + '$', 'i'), '')
    .trim();
  try { return JSON.parse(text); } catch {}
  const start = text.indexOf('{'), end = text.lastIndexOf('}');
  if (start >= 0 && end > start) { try { return JSON.parse(text.slice(start, end + 1)); } catch {} }
  return fallback;
}

let base;
try { base = $('Parse User Request').item.json; } catch { base = $json; }
const decision = base.needs_conversation_agent
  ? parseJsonSafe($json.text ?? $json.output ?? $json.response ?? $json, null)
  : null;

const out = { ...base };
if (decision) {
  out.conversation_agent_used = true;
  out.intent = decision.intent && decision.intent !== 'unknown' ? decision.intent : out.intent;
  out.region_query = decision.region || (decision.use_saved_region ? out.conversation_memory?.last_region : out.region_query);
  out.requested_stakeholder = decision.stakeholder && decision.stakeholder !== 'none' ? decision.stakeholder : out.requested_stakeholder;
  out.actions_requested = Boolean(decision.needs_action_agent || out.actions_requested);
  out.asks_evidence = Boolean(decision.needs_osint_agent || out.asks_evidence || out.intent === 'evidence');
  if (decision.direct_response || decision.needs_region) {
    out.direct_response = {
      ok: !decision.needs_region,
      error: decision.needs_region ? 'REGION_REQUIRED' : undefined,
      response_kind: decision.needs_region ? 'REGION_REQUIRED' : 'CONVERSATIONAL',
      overall_threat_level: 'NONE',
      correlation_status: 'NOT_APPLICABLE',
      regional_summary: decision.direct_response || 'Which city, state, province, or country should I check?',
      awaiting_region: Boolean(decision.needs_region),
    };
  }
  out.conversation_decision = decision;
}

if (out.cached_followup && out.cached_assessment) {
  if (out.cached_severity || out.intent === 'severity_followup') {
    out.cached_severity = true;
    out.cached_action = false;
    out.cached_evidence = false;
    out.needs_geocode = false;
  } else if (out.cached_evidence || out.intent === 'evidence_followup') {
    out.cached_evidence = true;
    out.cached_action = false;
    out.cached_severity = false;
    out.needs_geocode = false;
  } else if (out.intent === 'actions') {
    out.cached_action = true;
    out.needs_geocode = false;
    const _ca = out.cached_assessment || {};
    out.action_assessment = { region: _ca.region, overall_threat_level: _ca.overall_threat_level, correlation_status: _ca.correlation_status, regional_summary: _ca.regional_summary, threats: _ca.threats, evidence: (Array.isArray(_ca.evidence) ? _ca.evidence.slice(0, 5) : []) };
  } else {
    out.direct_response = {
      ...out.cached_assessment,
      ok: true,
      response_kind: 'CACHED_EVIDENCE_FOLLOWUP',
      regional_summary: 'Using the latest saved assessment for ' + out.region_query + '. ' + (out.cached_assessment.regional_summary || ''),
    };
  }
}

out.needs_geocode = !out.direct_response && !out.cached_severity && !out.cached_evidence && !out.cached_action && Boolean(out.region_query);
return [{ json: out }];

// Save Conversation State — compute the memory object to persist. The actual
// write happens in the downstream "Persist Data Table Memory" upsert node,
// which reads $json.conversation_memory_after produced here.
const response = $json;
let parsed = {};
try { parsed = $('Parse User Request').item.json; } catch (e) {}
const current = (parsed && parsed.conversation_memory) || response.conversation_memory_before || {};
const before = response.conversation_memory_before || current || {};

const session = parsed.session_id || response.session_id || 'anonymous';
const region = response.active_region || response.region || parsed.region_query || current.last_region || '';
const pending = response.pending_intent || response.restored_pending_intent || parsed.pending_intent || parsed.restored_pending_intent || current.pending_intent || '';
const isRegionRequired = Boolean(response.awaiting_region || response.error === 'REGION_REQUIRED' || response.response_kind === 'REGION_REQUIRED');
const shouldKeepPending = isRegionRequired || response.error === 'REGION_NOT_FOUND';
const lastAssessment = response.ok !== false && !['GREETING', 'HELP', 'REGION_REQUIRED', 'WEATHER_ONLY', 'CACHED_ACTION_FOLLOWUP', 'CACHED_SEVERITY_FOLLOWUP', 'CACHED_EVIDENCE_FOLLOWUP'].includes(response.response_kind || '') && response.error !== 'REGION_REQUIRED'
  ? {
      region: response.region || region,
      overall_threat_level: response.overall_threat_level || '',
      correlation_status: response.correlation_status || '',
      regional_summary: response.regional_summary || '',
      threats: Array.isArray(response.threats) ? response.threats.slice(0, 5) : [],
      evidence: Array.isArray(response.evidence) ? response.evidence.slice(0, 3) : [],
      probable_causes: Array.isArray(response.probable_causes) ? response.probable_causes.slice(0, 2) : [],
      recommended_actions: response.recommended_actions || {},
      priority_message: response.priority_message || '',
      source_status: response.source_status || {},
    }
  : (current.last_assessment || null);

const after = {
  session_id: session,
  active_region: isRegionRequired ? (current.active_region || current.last_region || '') : region,
  last_region: isRegionRequired ? (current.last_region || '') : region,
  region_key: isRegionRequired ? (current.region_key || '') : (response.region_key || current.region_key || ''),
  latitude: isRegionRequired ? (current.latitude ?? null) : (response.latitude ?? current.latitude ?? null),
  longitude: isRegionRequired ? (current.longitude ?? null) : (response.longitude ?? current.longitude ?? null),
  last_intent: parsed.intent || current.last_intent || '',
  pending_intent: shouldKeepPending ? (pending || 'general_threats') : '',
  last_pending_intent: pending || current.last_pending_intent || '',
  last_stakeholder: parsed.requested_stakeholder || current.last_stakeholder || '',
  last_threat_level: response.overall_threat_level || current.last_threat_level || '',
  last_threats: Array.isArray(response.threats) ? response.threats.slice(0, 5) : (current.last_threats || []),
  last_assessment: lastAssessment,
  awaiting_region: Boolean(shouldKeepPending),
  updated_at: new Date().toISOString(),
};

return [{ json: { ...response, conversation_memory_before: before, conversation_memory_after: after, memory_save_ok: true, memory_save_error: '' } }];

parameters.text:
=Use only this correlated assessment. Return JSON only. Max 3 short actions for requested stakeholder and max 2 for other relevant stakeholders. Do not create actions for unaffected groups.
Schema: {"urgency":"ROUTINE|MONITOR|PROMPT|IMMEDIATE","priority_message":"","actions":{"farmers":[],"grid_operators":[],"emergency_authorities":[],"logistics_operators":[],"local_government":[],"general_public":[]},"monitoring_next":[],"safety_note":""}
REQUESTED_STAKEHOLDER: {{ $json.requested_stakeholder }}
ASSESSMENT:
{{ JSON.stringify($json.action_assessment || {}) }}
Asia scope and grounding: Use the exact resolved Asian city/country and coordinates in the input. Treat API observations as evidence, distinguish observed data from inference, never substitute a global demo region, and never invent measurements, alerts, sources, or certainty. Sound calm, friendly, and human; acknowledge worry or discomfort without pretending to feel emotions. If the selected location exists, never ask for it again. When response_language is ur, answer naturally in Urdu; otherwise answer in English. Use response_variant and repeated_question_count so repeated questions get a fresh explanation angle and follow-up instead of copied wording. For a standard query, use short paragraphs, headings, the threat level, strongest evidence, and 3 practical actions within 300 words. For an explicit comprehensive or detailed threat report, expand to at most 450 words with severity, evidence by source, affected sectors, stakeholder actions, monitoring triggers, limitations, and a concise source list. Reuse cached assessment data for follow-ups and only call OSINT/action agents when the requested evidence or action is not already available.

parameters.jsCode:
function getNodeJson(name){ try{ return $(name).item.json; }catch{ return null; } }
const acd=getNodeJson('Apply Conversation Decision')||$json||{};
const parsed=getNodeJson('Parse User Request')||{};
const ca=acd.cached_assessment||acd.action_assessment||{};

// ---- Region display (dedupe repeated admin segments, e.g. "Punjab, Punjab, Pakistan") ----
function cleanRegion(value){
  const parts=String(value||'').split(',').map((p)=>p.trim()).filter(Boolean);
  const out=[];
  for(const p of parts){ const pl=p.toLowerCase(); if(out.some((q)=>q.toLowerCase()===pl))continue; const redundant=parts.some((o)=>{ const ol=o.toLowerCase(); if(o===p||ol.length<=pl.length)return false; return (' '+ol+' ').indexOf(' '+pl+' ')!==-1; }); if(redundant)continue; out.push(p); }
  return out.join(', ');
}
const regionDisplay=cleanRegion(ca.region||acd.active_region||acd.region_query||'this region');
const regionName=ca.region||acd.active_region||acd.region_query||'';

// ---- Stakeholder detection: current message wins, then saved memory, then general_public ----
const stakeholder=parsed.requested_stakeholder||acd.requested_stakeholder||(ca.last_stakeholder)||'general_public';
const headingMap={
  farmers:'What farmers should do',
  general_public:'What the general public should do',
  emergency_authorities:'What emergency authorities should do',
  logistics_operators:'What logistics operators should do',
  grid_operators:'What grid operators should do',
  local_government:'What local government should do',
};
const heading=headingMap[stakeholder]||('What '+String(stakeholder).replace(/_/g,' ')+' should do');

// ---- Saved threat level ----
const level=String(ca.overall_threat_level||'LOW').toUpperCase();
const active=level==='MEDIUM'||level==='HIGH'||level==='CRITICAL';

// ---- Threat-type detection from the saved assessment (deterministic, no LLM) ----
const haystack=[Array.isArray(ca.threats)?ca.threats.join(' '):'',Array.isArray(ca.evidence)?ca.evidence.join(' '):'',ca.regional_summary||''].join(' ').toLowerCase();
const types={
  rain:/flood|rain|precipitation|waterlog|inundat|monsoon/.test(haystack),
  wind:/wind|gust|storm|cyclone|gale/.test(haystack),
  heat:/heat|humid|temperature|hot|feels-like|feels like|heat index/.test(haystack),
  fire:/fire|wildfire|smoke|burn/.test(haystack),
  cold:/cold|snow|frost|freeze|freezing/.test(haystack),
  disaster:/earthquake|tsunami|volcan|landslide|disaster alert|gdacs/.test(haystack),
};

// ---- Evidence-based escalation: urgent actions ONLY when the saved evidence confirms a
//      specific serious hazard. Never inferred from precipitation probability alone. ----
const caStr=JSON.stringify(ca||{});
// Severe rainfall amount / accumulation / official warning (same signal the wording scrub uses)
const hasRainEvidence=/\d+(?:\.\d+)?\s*mm|rainfall of|accumulat|red alert|orange alert|official warning|severe weather warning|flood warning/i.test(caStr);
const confirmedFlooding=/flood warning|flash flood|floodwater|inundation|flooding is (?:occurring|underway|reported|confirmed)|active flooding|ongoing flood/i.test(caStr);
const officialEvacuation=/evacuat/i.test(caStr);
const activeWildfire=/active (?:wild)?fire|wildfire (?:is )?(?:active|spreading|burning)|actively burning|fire detected|fire is spreading|hotspot detected/i.test(caStr);
// Dangerous wind: numeric gust >= 75 km/h, or explicit severe-wind wording. Probability text ignored.
let maxGust=0; const gm=caStr.match(/(\d+(?:\.\d+)?)\s*km\/h/gi)||[]; for(const g of gm){ const n=parseFloat(g); if(!isNaN(n)&&n>maxGust)maxGust=n; }
const dangerousWind=maxGust>=75||/damaging wind|destructive wind|gale warning|storm warning|hurricane|cyclone warning/i.test(caStr);
const escalate=hasRainEvidence||confirmedFlooding||officialEvacuation||activeWildfire||dangerousWind;

const baseLevel=(level==='HIGH'||level==='CRITICAL')?'HIGH':(level==='MEDIUM'?'MEDIUM':'LOW');
const effectiveLevel=escalate?'HIGH':baseLevel;

// ---- Level-aware templates: stakeholder -> level -> (type map for MEDIUM/HIGH) ----
// LOW  = monitor and prepare (low-impact only; no evacuation / relocation / emergency deployment)
// MEDIUM = take precautions (drainage, protect assets, relocate vulnerable items only if likely)
// HIGH = act immediately (move people/livestock/assets, suspend operations, evacuate, reroute)
const T={
  farmers:{
    low:[
      'Monitor official weather forecasts and updates.',
      'Inspect field drainage and equipment.',
      'Secure lightweight outdoor items and loose equipment.',
      'Adjust irrigation only if rainfall develops.',
      'Continue normal operations with routine caution.',
    ],
    medium:{
      rain:['Clear field and farm drainage channels ahead of rainfall.','Protect exposed crops and cover vulnerable seedlings.','Relocate vulnerable stored items if waterlogging becomes likely.'],
      wind:['Secure loose equipment, sheeting, and greenhouse structures.','Stake or shelter vulnerable standing crops against strong wind.','Move lightweight or exposed items to sheltered storage if strong wind becomes likely.'],
      heat:['Shift fieldwork to cooler morning or evening hours.','Provide water and shade for workers and livestock.','Monitor crop moisture and adjust irrigation carefully.'],
      fire:['Clear dry vegetation and maintain firebreaks around fields and buildings.','Keep water and basic firefighting tools accessible.','Prepare to move livestock and stored feed if fire risk rises.'],
      cold:['Protect sensitive crops with cover or mulch against frost.','Prepare shelter for vulnerable livestock.','Protect water lines and irrigation from freezing.'],
      disaster:['Follow official agricultural and civil-defence advisories.','Prepare to move livestock and inputs if conditions worsen.','Keep emergency supplies and communications ready.'],
      generic:['Clear drainage and protect exposed crops and equipment.','Prepare farm staff and emergency resources.','Relocate vulnerable items if conditions worsen.'],
    },
    high:{
      rain:['Move livestock and stored produce out of flood-prone areas now.','Move seed, inputs, and equipment to higher, covered storage.','Suspend field operations in waterlogged or unsafe areas.'],
      wind:['Move livestock and equipment away from exposed areas and weak structures.','Secure or remove anything that could be damaged or become airborne.','Suspend unsafe outdoor operations.'],
      heat:['Reduce strenuous fieldwork and work during cooler morning or evening hours.','Provide water and shade for workers and livestock, and watch for heat stress.','Monitor crop moisture and adjust irrigation carefully.','Limit strenuous activity during peak afternoon heat.','Follow official heat-advisory guidance.'],
      fire:['Move livestock, workers, and stored feed away from the fire path now.','Follow evacuation and official emergency instructions.','Suspend operations in threatened areas.'],
      cold:['Move vulnerable livestock into insulated shelter now.','Protect or drain water systems against a hard freeze.','Suspend unsafe outdoor operations.'],
      disaster:['Move livestock, people, equipment, and supplies from danger zones now.','Activate emergency plans and follow official instructions.','Suspend operations in affected areas.'],
      generic:['Move livestock, people, equipment, and supplies from danger zones now.','Suspend unsafe operations and follow official emergency instructions.','Keep emergency supplies and communications ready.'],
    },
  },
  general_public:{
    low:[
      'Monitor official weather updates and local alerts.',
      'Keep phones charged and note local emergency contacts.',
      'Secure lightweight outdoor items.',
      'Avoid acting on unconfirmed reports.',
      'Continue normal activity with routine caution.',
    ],
    medium:{
      rain:['Avoid low-lying, flood-prone roads and underpasses.','Do not walk or drive through moving water.','Prepare for possible local disruption and keep alerts on.'],
      wind:['Secure loose outdoor objects and stay clear of trees and weak structures.','Delay non-essential travel during peak winds.','Stay away from windows in strong gusts.'],
      heat:['Stay hydrated and limit strenuous outdoor activity in peak heat.','Stay in shade or cooled spaces during the hottest hours.','Check on elderly, children, and vulnerable neighbours.'],
      fire:['Monitor air-quality and evacuation guidance from authorities.','Keep windows closed and limit smoke exposure.','Prepare a go-bag in case conditions worsen.'],
      cold:['Dress in warm layers and limit time in extreme cold.','Heat living spaces safely and watch for carbon-monoxide risk.','Check on elderly and vulnerable neighbours.'],
      disaster:['Follow official advisories and prepare an emergency kit.','Know local shelter and evacuation routes.','Stay tuned to official channels for updates.'],
      generic:['Monitor official local alerts and weather updates.','Avoid unnecessary travel in affected areas.','Prepare for possible disruption.'],
    },
    high:{
      rain:['Move to higher ground and away from floodwater now.','Do not enter flooded roads, underpasses, or waterways.','Follow evacuation and official emergency instructions.'],
      wind:['Shelter indoors away from windows during dangerous winds.','Avoid all non-essential travel and stay clear of falling hazards.','Follow official emergency instructions.'],
      heat:['Stop outdoor exertion and move to cooling immediately.','Seek medical help for heat-illness symptoms.','Check urgently on vulnerable people.'],
      fire:['Evacuate now if instructed and follow official routes.','Avoid smoke and keep away from the fire path.','Follow all emergency instructions.'],
      cold:['Stay indoors and keep warm during extreme cold.','Seek warming shelter if heating fails.','Check urgently on vulnerable people.'],
      disaster:['Follow evacuation orders and official emergency instructions now.','Move away from danger zones immediately.','Keep an emergency kit and documents ready.'],
      generic:['Follow official emergency instructions and any evacuation orders now.','Move away from danger zones immediately.','Keep emergency supplies ready.'],
    },
  },
  emergency_authorities:{
    low:['Monitor official alerts and situation reports.','Review response plans and confirm on-call readiness.','Keep the public informed with routine guidance.'],
    medium:{ generic:['Pre-position response resources in likely-affected areas.','Verify communications, shelters, and evacuation routes.','Coordinate with local agencies and update the public.'] },
    high:{ generic:['Activate the emergency operations plan and response teams now.','Direct evacuations and close or reroute dangerous areas.','Coordinate agencies and issue urgent public warnings.'] },
  },
  logistics_operators:{
    low:['Monitor route and weather conditions.','Review contingency routing options.','Continue normal operations with routine caution.'],
    medium:{ generic:['Plan around affected corridors and avoid low-lying routes.','Protect cargo and depots from likely weather impact.','Prepare contingency routing and buffer schedules.'] },
    high:{ generic:['Suspend routing through danger zones now.','Reroute fleets away from closed or unsafe corridors.','Coordinate with authorities on open routes.'] },
  },
  grid_operators:{
    low:['Monitor grid load and weather impact.','Inspect the status of vulnerable infrastructure.','Keep restoration crews on routine standby.'],
    medium:{ generic:['Inspect and reinforce exposed lines and assets.','Pre-stage restoration crews for possible outages.','Monitor load and prepare for fault isolation.'] },
    high:{ generic:['Isolate damaged sections and prioritise critical facilities now.','De-energise unsafe lines as needed.','Deploy restoration crews as access allows.'] },
  },
  local_government:{
    low:['Monitor official alerts.','Review local contingency plans.','Keep residents informed with routine guidance.'],
    medium:{ generic:['Issue localised advisories and clear public drainage.','Ready shelters and support for vulnerable residents.','Coordinate with emergency services.'] },
    high:{ generic:['Activate contingency plans and issue urgent public warnings now.','Open shelters and coordinate evacuations.','Close or reroute dangerous public areas.'] },
  },
};

const stakeObj=T[stakeholder]||T.general_public;
const order=['rain','wind','heat','fire','cold','disaster'];

// ---- Prioritize the highest-risk threat type ----
// Score each detected threat type by the highest severity of the saved threats
// that reference it, so the most serious threat's actions are listed first while
// still including every saved threat type.
const typePatterns={
  rain:/flood|rain|precipitation|waterlog|inundat|monsoon/i,
  wind:/wind|gust|storm|cyclone|gale/i,
  heat:/heat|humid|temperature|hot|feels[- ]?like|heat index|arid|dry/i,
  fire:/fire|wildfire|smoke|burn/i,
  cold:/cold|snow|frost|freeze|freezing/i,
  disaster:/earthquake|tsunami|volcan|landslide|disaster alert|gdacs/i,
};
function sevRank(s){ const v=String(s||'').toUpperCase(); if(v==='CRITICAL')return 4; if(v==='HIGH')return 3; if(v==='MEDIUM')return 2; if(v==='LOW')return 1; return 0; }
function threatBlob(x){ if(x&&typeof x==='object')return [x.type,x.description,x.short_finding,x.detail,x.title].filter(Boolean).join(' '); return String(x||''); }
const savedThreats=Array.isArray(ca.threats)?ca.threats:[];
const savedEvidence=Array.isArray(ca.evidence)?ca.evidence:[];
// Priority ranking: the OSINT agent lists threats in priority order, so an
// earlier position = higher priority. When explicit per-threat severity exists,
// it takes precedence. typeScore holds the highest severity seen (0 if none);
// typePos holds the earliest threat-array index a type appears at (lower = more
// important). Evidence order is used as a secondary position signal.
const typeScore={}; const typePos={};
for(const k of order){ typeScore[k]=types[k]?0:0; if(types[k])typePos[k]=999; }
function scan(list,base){ for(let i=0;i<list.length;i++){ const blob=threatBlob(list[i]); const rank=sevRank(list[i]&&list[i].severity); for(const k of order){ if(typePatterns[k].test(blob)){ types[k]=true; if(rank>(typeScore[k]||0))typeScore[k]=rank; const pos=base+i; if(typePos[k]===undefined||pos<typePos[k])typePos[k]=pos; } } } }
scan(savedThreats,0);
scan(savedEvidence,100);
// Detected types ordered by: explicit severity desc, then earliest position asc,
// then canonical order. This surfaces the dominant threat's actions first
// (e.g. heat listed first by OSINT) while still including every saved type.
const detectedOrder=order.filter((k)=>types[k]).sort((a,b)=>{
  const ds=(typeScore[b]||0)-(typeScore[a]||0); if(ds!==0)return ds;
  const dp=(typePos[a]===undefined?999:typePos[a])-(typePos[b]===undefined?999:typePos[b]); if(dp!==0)return dp;
  return order.indexOf(a)-order.indexOf(b);
});

// Highest saved threat-type severity (0..4). Lets a dominant hazard (e.g. HIGH
// "extreme heat" threat) drive type-specific precautions even when the OVERALL
// level is LOW — so farmer heat advice appears when heat is the main threat.
let maxTypeSev=0; for(const k of detectedOrder){ const sc=(typeScore[k]||0); if(sc>maxTypeSev)maxTypeSev=sc; }
// Template tier: escalation/HIGH -> high; otherwise use the highest of the overall
// level and the dominant threat-type severity (MEDIUM+ threat => precaution tier).
let tier;
if(effectiveLevel==='HIGH'){ tier='high'; }
else if(effectiveLevel==='MEDIUM'||maxTypeSev>=2){ tier='medium'; }
else { tier='low'; }

// Build candidate step pool matched to the tier, highest-risk threat first.
let pool=[];
if(tier==='low'){
  pool=(stakeObj.low||[]).slice();
} else {
  const tierMap=(tier==='high'?stakeObj.high:stakeObj.medium)||{};
  if(detectedOrder.length){ for(const t of detectedOrder){ if(Array.isArray(tierMap[t])) pool=pool.concat(tierMap[t]); } }
  if(pool.length<3&&Array.isArray(tierMap.generic)) pool=pool.concat(tierMap.generic);
  if(pool.length<3&&Array.isArray(stakeObj.low)) pool=pool.concat(stakeObj.low);
}

// de-duplicate, keep order, cap 3..5
const seen=new Set(); const steps=[];
for(const s of pool){ const k=s.toLowerCase(); if(seen.has(k))continue; seen.add(k); steps.push(s); if(steps.length>=5)break; }
const actions=steps.slice(0,Math.max(3,Math.min(5,steps.length)));
const numbered=actions.map((a,i)=>(i+1)+'. '+String(a).replace(/^\s*\d+[.)]\s*/,'').trim());

// ---- Natural source sentence ----
function naturalJoin(arr){ arr=(arr||[]).filter(Boolean); if(arr.length<=1)return arr[0]||''; if(arr.length===2)return arr[0]+' and '+arr[1]; return arr.slice(0,-1).join(', ')+', and '+arr[arr.length-1]; }
const successful=(ca.source_status&&Array.isArray(ca.source_status.successful)&&ca.source_status.successful.length)?ca.source_status.successful:['Open-Meteo','GDACS'];
const sourceSentence='This assessment is based on data from '+naturalJoin(successful)+'.';

// ---- Evidence limitation (only when a real gap exists; never "Gaps: none") ----
const gaps=(ca.source_status&&Array.isArray(ca.source_status.failed_or_unconfigured))?ca.source_status.failed_or_unconfigured.filter(Boolean):[];
const limitationLine=gaps.length?('\n\nEvidence limitation: '+gaps.map((g)=>String(g).replace(/\.*$/,'')).join('; ')+'.'):'';

// ---- Rain wording safety: don't call precipitation probability "heavy rain" without amount/intensity/warning ----
function scrubRain(text){
  let t=String(text||'');
  if(hasRainEvidence)return t;
  t=t.replace(/imminent heavy precipitation/gi,'a high chance of precipitation');
  t=t.replace(/imminent heavy rainfall/gi,'a high chance of precipitation');
  t=t.replace(/imminent heavy rain/gi,'a high chance of precipitation');
  t=t.replace(/severe rainfall/gi,'a high chance of precipitation');
  t=t.replace(/severe precipitation/gi,'a high chance of precipitation');
  t=t.replace(/heavy precipitation/gi,'precipitation');
  t=t.replace(/heavy rainfall is (?:expected|forecast|likely|imminent)/gi,'a high chance of precipitation is forecast, but heavy rainfall is not currently confirmed');
  t=t.replace(/heavy rain is (?:expected|forecast|likely|imminent)/gi,'a high chance of precipitation is forecast, but heavy rainfall is not currently confirmed');
  t=t.replace(/heavy rainfall/gi,'precipitation');
  t=t.replace(/heavy rain/gi,'precipitation');
  return t;
}

// ---- Severe-weather wording safety (no unsupported "severe weather system") ----
const hasSevereEvidence=/red alert|orange alert|official warning|severe weather warning|flood warning|cyclone warning|storm warning|gale warning|tornado warning|hurricane warning|evacuat/i.test(caStr);
function scrubSevere(text){
  let t=String(text||'');
  if(hasSevereEvidence)return t;
  t=t.replace(/approaching severe weather system/gi,'an elevated chance of precipitation with moderate wind gusts');
  t=t.replace(/approaching storm system/gi,'an elevated chance of precipitation with moderate wind gusts');
  t=t.replace(/(?:potential|possible|approaching|imminent|expected|developing|likely) severe weather/gi,'an elevated chance of precipitation with moderate wind gusts');
  t=t.replace(/severe weather (?:system|is )?(?:approaching|imminent|expected|developing|likely)/gi,'an elevated chance of precipitation with moderate wind gusts');
  t=t.replace(/(?:possible |potential |approaching )?(?:approaching )?storms?(?: system)?/gi,'unsettled weather');
  t=t.replace(/severe weather system/gi,'unsettled weather');
  t=t.replace(/severe (?:thunder)?storm(?:s)?/gi,'unsettled weather');
  t=t.replace(/severe weather/gi,'unsettled weather');
  return t;
}

// ---- One short context sentence from the saved assessment (decimal-safe split) ----
function firstSentenceOf(text){
  const s=String(text||''); let cur='';
  for(let i=0;i<s.length;i++){ const ch=s[i]; cur+=ch; if(ch==='.'||ch==='!'||ch==='?'){ const prev=s[i-1],next=s[i+1]; if(ch==='.'&&/\d/.test(prev||'')&&/\d/.test(next||''))continue; if(next===undefined||/\s/.test(next))return cur.trim(); } }
  return cur.trim();
}
let summary=String(ca.regional_summary||'').trim();
let contextSentence=scrubSevere(scrubRain(firstSentenceOf(summary)));
if(!contextSentence){ contextSentence='The overall threat level is '+String(ca.overall_threat_level||'LOW').toLowerCase()+' based on the latest assessment.'; }

const chat_message=regionDisplay+' context: '+contextSentence+'\n\n'+heading+':\n'+numbered.join('\n')+'\n\n'+sourceSentence+limitationLine;

const urgency=effectiveLevel==='HIGH'?'PROMPT':(effectiveLevel==='MEDIUM'?'MONITOR':'ROUTINE');
const priority_message=ca.priority_message||('The overall threat level for '+regionDisplay+' is '+level.toLowerCase()+'. Take precautionary steps matched to the current conditions.');

return [{ json: {
  ok:true, system:'WIaaS CrisisLens', api_only:true, backend_used:false,
  source_channel: acd.source_channel||parsed.source_channel||'webhook',
  session_id: acd.session_id||parsed.session_id,
  response_kind:'CACHED_ACTION_FOLLOWUP',
  region: regionName, resolved_location: regionName,
  active_region: acd.active_region||regionName, region_key: acd.region_key||'',
  latitude: acd.latitude??null, longitude: acd.longitude??null,
  selected_route:'action_from_memory',
  requested_stakeholder: stakeholder,
  stakeholder_heading: heading,
  chat_message,
  overall_threat_level: ca.overall_threat_level||'LOW',
  correlation_status: ca.correlation_status||'PARTIALLY_SUPPORTED',
  regional_summary: '',
  context_sentence: contextSentence,
  numbered_actions: numbered,
  action_level: effectiveLevel,
  threats: Array.isArray(ca.threats)?ca.threats:[],
  evidence: Array.isArray(ca.evidence)?ca.evidence:[],
  probable_causes: Array.isArray(ca.probable_causes)?ca.probable_causes:[],
  recommended_actions: { [stakeholder]: actions },
  stakeholder_actions: actions,
  urgency,
  priority_message,
  monitoring_next: ['Open-Meteo weather','GDACS alerts'],
